      "path": "src/shell.ts",
      "content": "/**\n * WSL Service Provider for the `ctx.shell` capability seam. Every command\n * runs inside one WSL distribution as `wsl.exe -d <distro> [-u <user>]\n * --cd <linux cwd> -e bash -lc <command>`, so the model-facing bash dialect\n * matches the execution world exactly — the \"like direct calls\" experience\n * of a WSL workspace session.\n *\n * The executor is a fresh implementation modeled on\n * `@deepseek-ai/dsh-bash-local` (same deadline fusion, bounded collect,\n * background adaptation) but does NOT register the shared `shell` settings\n * namespace: the host composition already registers it through its own\n * executor, and a second registration from a preset realm would collide.\n * Configuration rides the preset row instead.\n * @module dsh-wsl-workspace/shell\n */\n\nimport { Context } from '@deepseek-ai/cordis'\nimport z from '@deepseek-ai/schemastery'\nimport { ShellExecutor } from '@deepseek-ai/dsh-shell'\nimport type {\n  CollectedOutput,\n  ShellExecution,\n  ShellExecRequest,\n  ShellExecSpec,\n  ShellProcess,\n  ShellProcessRead,\n  ShellRunResult,\n} from '@deepseek-ai/dsh-shell'\nimport type {\n  SubprocessCollect,\n  SubprocessHandle,\n  SubprocessOutputReader,\n  SubprocessSpawnSpec,\n} from '@deepseek-ai/dsh-subprocess'\nimport { clampTimeout, deadline, MAX_TIMER_DELAY_MS, timeoutOf } from '@deepseek-ai/dsh-timeout'\nimport {\n  isWindowsPathShaped,\n  isValidWslUsername,\n  joinUnc,\n  parseWslUnc,\n  windowsToMntPath,\n} from './shared/paths.ts'\nimport { getWorkspaceUsername } from './shared/wsl-credentials.ts'\nimport { defaultDistroSync } from './shared/wsl.ts'\n\n/**\n * Model-friendly environment overrides (same set `dsh-bash-local` hardcodes):\n * disable colors, pagers, and interactive terminal features that would garble\n * tool output. These values cross into the Linux process through WSLENV.\n */\nconst ENV_OVERRIDES = {\n  NO_COLOR: '1',\n  TERM: 'dumb',\n  PAGER: 'cat',\n  GIT_PAGER: 'cat',\n} as const\n\n/** Default SIGTERM→SIGKILL grace period (matches `dsh-bash-local`). */\nconst DEFAULT_GRACE_MS = 3_000\n\n/** Default per-stream spill cap (matches `dsh-bash-local`). */\nconst DEFAULT_MAX_SPILL_BYTES = 64 * 1024 * 1024\n\n/** Plugin config (all optional — `static Config` supplies the defaults). */\nexport interface Config {\n  /** Default working directory (a WSL UNC or Linux path); per-call workdir wins. */\n  cwd?: string\n  /**\n   * Default distribution used only when a call's workdir carries no distro\n   * (UNC workdirs always do; Linux/Windows drive workdirs do not).\n   */\n  distro?: string\n  /**\n   * Linux user bash runs as when the call carries no per-workspace user\n   * (`wsl.exe -u <username>`); undefined/empty = the distro default user.\n   */\n  username?: string\n  /** The `wsl.exe` executable (absolute path or PATH name). */\n  wslPath?: string\n  /** Start bash as a login shell (`-lc`) so user profile PATHs (nvm, cargo…) load. */\n  loginShell?: boolean\n  /** Default foreground timeout in milliseconds. */\n  timeoutMs?: number\n  /** Upper bound for per-call timeout overrides. */\n  maxTimeoutMs?: number\n  /** Per-stream in-memory output cap; overflow spills to a temp file. */\n  maxOutputBytes?: number\n  /** Per-stream spill-file cap; larger streams retain only their in-memory tail. */\n  maxSpillBytes?: number\n  /** Grace period for kill escalation and inherited pipes; at most `MAX_TIMER_DELAY_MS`. */\n  graceMs?: number\n}\n\n/** The shape after schemastery applied the defaults. */\ntype ResolvedConfig = Required<Omit<Config, 'cwd' | 'distro' | 'username'>> & Pick<Config, 'cwd' | 'distro' | 'username'>\n\n/** Project a settled collect-mode reader into the final CollectedOutput shape. */\nfunction finalOutput(reader: SubprocessOutputReader): CollectedOutput {\n  const read = reader.readFrom(0)\n  return {\n    text: read.text,\n    truncated: read.lossy,\n    ...read.spillPath !== undefined ? { spillPath: read.spillPath } : {},\n  }\n}\n\nfunction assertPositiveFinite(name: string, value: number): void {\n  if (!Number.isFinite(value) || value <= 0) {\n    throw new Error(`wsl-shell: ${name} must be a positive finite number`)\n  }\n}\n\n/**\n * Reject a resolved configuration this executor could not run with, so a\n * stored value is refused where it is written instead of failing at the next\n * command.\n * @param config - the schema-validated configuration.\n * @throws Error naming the field that cannot be used.\n */\nexport function assertServiceableWslConfig(config: Config): void {\n  const resolved = config as ResolvedConfig\n  assertPositiveFinite('timeoutMs', resolved.timeoutMs)\n  assertPositiveFinite('maxTimeoutMs', resolved.maxTimeoutMs)\n  assertPositiveFinite('maxOutputBytes', resolved.maxOutputBytes)\n  assertPositiveFinite('maxSpillBytes', resolved.maxSpillBytes)\n  assertPositiveFinite('graceMs', resolved.graceMs)\n  if (resolved.graceMs > MAX_TIMER_DELAY_MS) {\n    throw new Error(`wsl-shell: graceMs must be no greater than ${MAX_TIMER_DELAY_MS}`)\n  }\n  if (resolved.distro !== undefined && resolved.distro.trim() === '') {\n    throw new Error('wsl-shell: distro must be a non-empty distribution name')\n  }\n  if (resolved.username !== undefined && resolved.username !== '' && !isValidWslUsername(resolved.username)) {\n    throw new Error('wsl-shell: username must match the Linux username pattern [A-Za-z_][A-Za-z0-9_.-]*')\n  }\n}\n\n/** One translated execution plan: the Linux world coordinates plus the argv. */\ninterface WslPlan {\n  /** Distribution the command runs in. */\n  distro: string\n  /** Linux working directory handed to `wsl.exe --cd`. */\n  linuxCwd: string\n  /** A valid Windows directory for the `wsl.exe` process itself. */\n  windowsCwd: string\n  /** Environment map (ENV_OVERRIDES + caller env + dshEnv) with WSLENV set. */\n  env: Record<string, string>\n  /** Full argv to hand to `ctx.subprocess`. */\n  argv: readonly string[]\n}\n\n/**\n * WSL bash executor over the LOCAL subprocess service: `wsl.exe` is a Windows\n * executable, so the Windows-side spawn, bounded output, spill files, and\n * process-group termination are the local subprocess seam's mechanics; this\n * executor supplies the Linux-world argv, cwd translation, and WSLENV.\n */\nexport class WslShellExecutor extends ShellExecutor {\n  static inject = ['subprocess']\n\n  static Config: z<Config> = z.object({\n    cwd: z.string(),\n    distro: z.string(),\n    username: z.string(),\n    wslPath: z.string().default('wsl.exe'),\n    loginShell: z.boolean().default(true),\n    timeoutMs: z.number().default(120_000),\n    maxTimeoutMs: z.number().default(600_000),\n    maxOutputBytes: z.number().default(64_000),\n    maxSpillBytes: z.number().default(DEFAULT_MAX_SPILL_BYTES),\n    graceMs: z.number().default(DEFAULT_GRACE_MS),\n  })\n\n  private readonly resolved: ResolvedConfig\n\n  /** Validated config (schemastery applied the defaults before construction). */\n  get config(): ResolvedConfig {\n    return this.resolved\n  }\n\n  constructor(ctx: Context, config: Config) {\n    super(ctx)\n    const entry = config as ResolvedConfig\n    assertServiceableWslConfig(entry)\n    this.resolved = entry\n  }\n\n  /**\n   * Resolve a request into a fully-specified spec: fill `workdir` from\n   * `config.cwd`, and `timeoutMs` from `config.timeoutMs`, capped at\n   * `config.maxTimeoutMs`. The tool layer calls this before\n   * {@link execute}/{@link run}/{@link start}, so those methods receive explicit\n   * values. `onExpiry` is defaulted to `'kill'`; a background producer that must\n   * outlive `timeoutMs` resolves it to `'none'` instead.\n   */\n  resolve(request: ShellExecRequest): ShellExecSpec {\n    const timeoutMs = clampTimeout(\n      request.timeoutMs,\n      this.config.timeoutMs,\n      this.config.maxTimeoutMs,\n      'wsl-shell: request.timeoutMs',\n    )\n    const stdoutMaxBytes = request.stdoutMaxBytes ?? this.config.maxOutputBytes\n    assertPositiveFinite('request.stdoutMaxBytes', stdoutMaxBytes)\n    return {\n      command: request.command,\n      workdir: request.workdir ?? this.config.cwd ?? process.cwd(),\n      timeoutMs,\n      onExpiry: request.onExpiry ?? 'kill',\n      stdoutMaxBytes,\n      ...request.signal ? { signal: request.signal } : {},\n      ...request.stdin !== undefined ? { stdin: request.stdin } : {},\n      ...request.env !== undefined ? { env: request.env } : {},\n      ...request.dshEnv !== undefined ? { dshEnv: request.dshEnv } : {},\n      sandboxPolicy: request.sandboxPolicy,\n    }\n  }\n\n  /**\n   * Execute a resolved spec and return the live handle with its foreground\n   * projection. This is the seam shape the 0.2.x host calls —\n   * `await (await ctx.shell.execute(ctx.shell.resolve(request))).result()` — and\n   * a background caller uses the same handle's `readOutput`/`observed`/`kill`\n   * without ever calling {@link ShellExecution.result}, so it never observes that\n   * projection's rejection either.\n   * @param spec - the resolved execution spec.\n   * @returns the live execution handle.\n   */\n  async execute(spec: ShellExecSpec): Promise<ShellExecution> {\n    return this.spawnExecution(spec)\n  }\n\n  /**\n   * Translate a resolved spec into the Linux execution plan. Fails loud on a\n   * workdir that names neither the WSL world (UNC or Linux path) nor a\n   * Windows drive path (reached through `/mnt/<drive>`).\n   * @param spec - the resolved execution spec.\n   * @returns the translated plan, including the complete argv.\n   */\n  private plan(spec: ShellExecSpec): WslPlan {\n    const workdir = spec.workdir\n    let distro: string\n    let linuxCwd: string\n    let windowsCwd: string\n    let username: string | undefined\n    const unc = parseWslUnc(workdir)\n    if (unc !== null) {\n      distro = unc.distro\n      linuxCwd = unc.linuxPath\n      // The `wsl.exe` process itself needs a plain Windows directory: its own\n      // cwd is irrelevant (`--cd` sets the Linux side), and spawning with a\n      // UNC cwd is a documented Node/Windows edge. SystemRoot always exists.\n      windowsCwd = process.env.SystemRoot ?? process.cwd()\n      username = this.resolveUser(spec, joinUnc(unc.distro, unc.linuxPath))\n    } else if (workdir.startsWith('/')) {\n      distro = this.resolveDistro(spec)\n      linuxCwd = workdir\n      windowsCwd = process.cwd()\n      username = this.resolveUser(spec, undefined)\n    } else {\n      const mnt = windowsToMntPath(workdir)\n      if (mnt === null) {\n        throw new Error(`wsl-shell: workdir \"${workdir}\" is not in the WSL execution world`)\n      }\n      distro = this.resolveDistro(spec)\n      linuxCwd = mnt\n      windowsCwd = workdir\n      username = this.resolveUser(spec, undefined)\n    }\n    const env = this.withWslEnv(spec)\n    // A login shell (`-lc`) loads /etc/profile + the user profile chain, and\n    // several of those reset the cwd to $HOME (observed on Ubuntu 22.04 with\n    // a zsh user default: `wsl.exe --cd <dir> -e bash -lc 'pwd'` prints the\n    // home directory, while `-c` honors `--cd`). The model-facing cwd must\n    // be the resolved workdir in both modes, so prefix an explicit `cd`\n    // when the login shell runs. `cd` into a deleted directory fails the\n    // command exactly like `--cd` would; the failure text is unchanged.\n    const command = this.config.loginShell\n      ? `cd '${linuxCwd.replace(/'/g, `'\\\\''`)}' && ${spec.command}`\n      : spec.command\n    const argv = [\n      this.config.wslPath,\n      '-d', distro,\n      ...(username !== undefined && username !== '' ? ['-u', username] : []),\n      '--cd', linuxCwd,\n      '-e', 'bash',\n      this.config.loginShell ? '-lc' : '-c',\n      command,\n    ]\n    return { distro, linuxCwd, windowsCwd, env, argv }\n  }\n\n  /**\n   * Resolve the distribution for a workdir that carries none. The chain:\n   * the calling session's distribution (`DSH_WSL_DISTRO`, contributed by the\n   * host half from the session's UNC workspace cwd — the common case for a\n   * model passing a Linux `workdir`), then the configured `distro`, then the\n   * host's default distribution (cached registry read) as a last resort for\n   * plugin-driven calls with no session. Fails loud when every source is\n   * absent rather than guessing a distro the path does not belong to.\n   * @param spec - the resolved execution spec (its dshEnv carries the session fact).\n   * @returns the distribution name.\n   */\n  private resolveDistro(spec: ShellExecSpec): string {\n    const fromEnv = spec.dshEnv?.DSH_WSL_DISTRO\n    if (fromEnv !== undefined && fromEnv !== '') return fromEnv\n    const configured = this.config.distro\n    if (configured !== undefined && configured !== '') return configured\n    const fallback = defaultDistroSync()\n    if (fallback !== undefined) return fallback\n    throw new Error(\n      'wsl-shell: Linux workdir carries no distribution; no session DSH_WSL_DISTRO, distro config, '\n      + 'or default distribution is available',\n    )\n  }\n\n  /**\n   * Resolve the Linux user bash runs as. The chain: the calling session's\n   * workspace user (`DSH_WSL_USER`, contributed by the host half), then the\n   * workspace's stored username when the workdir is a UNC path, then the\n   * configured `username`. Absent everywhere, the distribution's default\n   * user runs. Invalid values are skipped (they were validated on write;\n   * the guard is defense in depth).\n   * @param spec - the resolved execution spec (its dshEnv carries the session fact).\n   * @param uncKey - canonical UNC key of the workdir when it is a UNC path.\n   * @returns the username, or undefined for the distro default user.\n   */\n  private resolveUser(spec: ShellExecSpec, uncKey: string | undefined): string | undefined {\n    const candidates = [\n      spec.dshEnv?.DSH_WSL_USER,\n      uncKey === undefined ? undefined : getWorkspaceUsername(uncKey),\n      this.config.username,\n    ]\n    for (const candidate of candidates) {\n      if (candidate !== undefined && candidate !== '' && isValidWslUsername(candidate)) return candidate\n    }\n    return undefined\n  }\n\n  /**\n   * Merge the caller env layers and inject `WSLENV` so the Windows-side\n   * values reach the Linux process. Windows-path-shaped values get the `/p`\n   * translation flag (they become `/mnt/<drive>/…` inside WSL); the ambient\n   * `WSLENV` value is preserved and extended.\n   * @param spec - the resolved execution spec.\n   * @returns the explicit environment map for the spawn.\n   */\n  private withWslEnv(spec: ShellExecSpec): Record<string, string> {\n    const env: Record<string, string> = { ...ENV_OVERRIDES, ...spec.env, ...spec.dshEnv }\n    const flags: string[] = []\n    for (const [key, value] of Object.entries(env)) {\n      if (key.toUpperCase() === 'WSLENV') continue\n      flags.push(isWindowsPathShaped(value) ? `${key}/p` : key)\n    }\n    const ambient = process.env.WSLENV\n    const merged = [ambient, flags.join(':')].filter(part => part !== undefined && part !== '').join(':')\n    env.WSLENV = merged\n    return env\n  }\n\n  /** Map a plan onto a fully-specified subprocess spawn. */\n  private spawnSpec(plan: WslPlan, spec: ShellExecSpec, stdoutMaxBytes: number, signal: AbortSignal | undefined): SubprocessSpawnSpec {\n    const collect = (maxBytes: number): SubprocessCollect =>\n      ({ maxBytes, spill: { maxBytes: this.config.maxSpillBytes } })\n    return {\n      argv: plan.argv,\n      cwd: plan.windowsCwd,\n      stdio: {\n        stdin: spec.stdin !== undefined ? { data: spec.stdin } : 'ignore',\n        stdout: collect(stdoutMaxBytes),\n        stderr: collect(this.config.maxOutputBytes),\n      },\n      graceMs: this.config.graceMs,\n      signal,\n      env: plan.env,\n    }\n  }\n\n  /** The collect-mode readers this executor requested (present by construction). */\n  private static collected(handle: SubprocessHandle): { stdout: SubprocessOutputReader; stderr: SubprocessOutputReader } {\n    const { stdout, stderr } = handle.collected\n    /* v8 ignore start -- collect dispositions expose both readers by the seam contract; defensive. */\n    if (stdout === undefined || stderr === undefined) {\n      throw new Error('wsl-shell: subprocess implementation dropped a requested collect stream')\n    }\n    /* v8 ignore stop */\n    return { stdout, stderr }\n  }\n\n  /**\n   * Run one command in the foreground and return its settled result. Kept\n   * because 0.1.x hosts and this plugin's own checks call it; on 0.2.x the host\n   * goes through {@link execute}, so both faces must stay in step — which they\n   * do by construction, since this is one line on top of that primitive.\n   */\n  async run(spec: ShellExecSpec): Promise<ShellRunResult> {\n    return this.spawnExecution(spec).result()\n  }\n\n  /**\n   * Start one command in the background and return its live handle. The host's\n   * background producers (and this plugin's `job_*` tools, via\n   * `src/host/wsl-jobs.ts`) resolve their request with `onExpiry: 'none'`, which\n   * is what leaves `timeoutMs` unarmed here; the deadline policy lives in the\n   * spec, not in this method.\n   */\n  start(spec: ShellExecSpec): ShellProcess {\n    return this.spawnExecution(spec)\n  }\n\n  /**\n   * The seam's only primitive: translate the spec, arm the deadline the spec\n   * asks for, spawn, and hand back the live handle.\n   *\n   * `onExpiry: 'none'` arms nothing — the caller's signal and {@link\n   * ShellProcess.kill} are then the only ways to stop the command, and\n   * `timeoutMs` is merely echoed into the result. Otherwise one fused deadline\n   * drives both the timeout and the caller's cancellation, so\n   * {@link ShellRunResult.timedOut} and `aborted` report the single first cause\n   * rather than both.\n   *\n   * The handle's `done` never rejects: a spawn that never produced a process\n   * settles as `killed` and leaves its story on the read path, while\n   * {@link ShellExecution.result} rejects for exactly that infrastructure\n   * failure. Nonzero exits, timeout kills, and abort kills all resolve.\n   * @param spec - the resolved execution spec.\n   * @returns the live execution handle, foreground-projectionable.\n   */\n  private spawnExecution(spec: ShellExecSpec): ShellExecution {\n    const plan = this.plan(spec)\n    const armed = spec.onExpiry === 'none'\n      ? undefined\n      : deadline(spec.signal, spec.timeoutMs, 'WSL_BASH_TIMEOUT')\n    // Explicit, not `using`: the deadline outlives this method, because a\n    // background handle is returned while its process is still running. It is\n    // released when the process settles, and on the one path that settles\n    // synchronously — a spawn that throws before producing a handle.\n    const release = (): void => armed?.[Symbol.dispose]()\n    let running: SubprocessHandle\n    try {\n      running = this.ctx.subprocess.spawn(\n        this.spawnSpec(plan, spec, spec.stdoutMaxBytes, armed?.signal ?? spec.signal),\n      )\n    } catch (error) {\n      release()\n      throw error\n    }\n    const collected = WslShellExecutor.collected(running)\n\n    // One branch per settlement cause, captured once so both `done` and the\n    // on-demand `result()` projection read the same facts.\n    type Settled =\n      | { ok: true; outcome: Awaited<SubprocessHandle['done']> }\n      | { ok: false; error: unknown }\n    const settled: Promise<Settled> = running.done.then(\n      (outcome): Settled => ({ ok: true, outcome }),\n      (error: unknown): Settled => ({ ok: false, error }),\n    )\n\n    // A spawn failure produces no process output, so the subprocess service has\n    // nothing to buffer; the note is delivered exactly once through the read path.\n    let spawnFailure: unknown\n    let failureNoted = false\n    const consumeSpawnFailure = (): string => {\n      if (spawnFailure === undefined || failureNoted) return ''\n      failureNoted = true\n      return `spawn failed: ${String(spawnFailure)}`\n    }\n\n    let stdoutOffset = 0\n    let stderrOffset = 0\nlet resultPromise: Promise<ShellRunResult> | undefined\n\n    /**\n     * The non-consuming observers `ShellProcess.observed` is required to carry.\n     *\n     * `observed` is **not optional** in the host's `ShellProcess` contract, and the host spells out\n     * what it is for: \"Independent observers read here at their own offsets without stealing bytes\n     * from `readOutput`.\" `dsh-jobs-local@0.2.x` drains a job's ring through offset readers and never\n     * calls `readOutput`, so a handle that offered only the latter shipped an empty `job_output`\n     * (issue #56).\n     *\n     * The offsets are **not** `stdoutOffset` / `stderrOffset` above: those track the consuming\n     * cursor, and sharing them would make the two readers steal bytes from each other. The host asks\n     * for independence explicitly.\n     *\n     * A rejected spawn leaves the subprocess service with nothing buffered, so `readFrom` yields an\n     * empty delta forever. The failure note is served as the **whole stderr stream** instead — once,\n     * to whichever observer asks first — because a reader cannot be told \"nothing happened, here is\n     * why\" any other way, and a job that never ran is exactly the case a user needs to see.\n     */\n    let spawnFailureObserved = false\n    const readObserved = (\n      which: 'stdout' | 'stderr',\n      from: number,\n    ): { text: string; nextOffset: number; lossy: boolean; spillPath?: string } => {\n      const read = collected[which].readFrom(from)\n      if (which === 'stderr' && read.text.length === 0 && !spawnFailureObserved) {\n        const note = consumeSpawnFailure()\n        if (note !== '') return { text: note, nextOffset: note.length, lossy: false }\n      }\n      if (which === 'stderr' && read.text.length > 0) spawnFailureObserved = true\n      return read\n    }\n\n    const execution: ShellExecution = {\n      status: 'running',\n      exitCode: null,\n      signal: null,\n      done: settled.then((settledValue) => {\n        release()\n        if (!settledValue.ok) {\n          spawnFailure = settledValue.error\n          execution.status = 'killed'\n          return\n        }\n        if (execution.status === 'running') {\n          execution.status = spec.signal?.aborted === true || settledValue.outcome.signal !== null\n            ? 'killed'\n            : 'completed'\n        }\n        execution.exitCode = settledValue.outcome.exitCode\n        execution.signal = settledValue.outcome.signal\n      }),\n      readOutput: (): ShellProcessRead => {\n        const out = collected.stdout.readFrom(stdoutOffset)\n        const err = collected.stderr.readFrom(stderrOffset)\n        stdoutOffset = out.nextOffset\n        stderrOffset = err.nextOffset\n        const errText = err.text.length > 0 ? err.text : consumeSpawnFailure()\n        const separator = out.text.length > 0 && !out.text.endsWith('\\n') ? '\\n' : ''\n        const delta = out.text\n          + (errText.length > 0 ? `${separator}[stderr]\\n${errText}` : '')\n        return {\n          delta,\n          lossy: out.lossy || err.lossy,\n          ...out.spillPath !== undefined ? { stdoutSpillPath: out.spillPath } : {},\n          ...err.spillPath !== undefined ? { stderrSpillPath: err.spillPath } : {},\n        }\n      },\n// Independent cursors over the same captured streams `readOutput` drains, so an observer can\n      // follow a background command without stealing bytes from the job tool that owns it. The\n      // `readObserved` wrapper (above) is main's: the readers themselves are the subprocess service's,\n      // which already keep independent offsets, and the wrapper adds what they cannot — a rejected\n      // spawn leaves them reading an empty stream forever, so the failure note is served as the whole\n      // stderr stream instead. This branch's `observed: { stdout: collected.stdout, … }` was the same\n      // idea without that half.\n      observed: {\n        stdout: { readFrom: from => readObserved('stdout', from) },\n        stderr: { readFrom: from => readObserved('stderr', from) },\n      },\n      kill: (): boolean => {\n        if (execution.status !== 'running') return false\n        execution.status = 'killed'\n        running.terminate()\n        return true\n      },\n      result: (): Promise<ShellRunResult> => {\n        if (resultPromise === undefined) {\n          resultPromise = settled.then((settledValue) => {\n            if (!settledValue.ok) throw settledValue.error\n            // Only this executor's timeout reason counts as timedOut; outer\n            // deadlines count as aborts.\n            const timedOut = armed !== undefined && timeoutOf(armed.signal, 'WSL_BASH_TIMEOUT') !== undefined\n            const aborted = armed?.signal.aborted === true && !timedOut\n            return {\n              ...settledValue.outcome,\n              timedOut,\n              aborted,\n              timeoutMs: spec.timeoutMs,\n              stdout: finalOutput(collected.stdout),\n              stderr: finalOutput(collected.stderr),\n            }\n          })\n        }\n        return resultPromise\n      },\n    }\n    return execution\n  }\n}\n\nexport default WslShellExecutor\n"
    },
    {
      "path": "src/host/wsl-bash-tool.ts",
      "content": "/**\n * The WSL world's `bash` tool, backed by a pipe-driven persistent shell.\n *\n * The model-facing contract is deliberately the host one-shot tool's: same `bash` name, same\n * `command`/`description`/`workdir`/`timeoutMs` parameters, same `{kind:'foreground', …}` output and\n * the same marker text (`[exit code: N]`, `[timed out after Nms]`, `[killed by signal: X]`). That is\n * not cosmetic. The session trace renders a call by tool name, and a `bash` call whose arguments\n * carry no `description` is classified as the persistent-shell variant and takes a different\n * rendering path — so matching the shape is what makes this tool indistinguishable from the one it\n * replaces.\n *\n * What differs is everything under the call. The host's persistent tool asks a terminal emulator\n * whether a sentinel line appeared, and issue #51 is what happens when the shell repaints that\n * line: three calls hung 303.8 s each in one real Desktop session before the host wiped the shell.\n * This tool asks a pipe for a record carrying this call's nonce.\n *\n * @module dsh-wsl-workspace/host/wsl-bash-tool\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport z from '@deepseek-ai/schemastery'\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport { randomUUID } from 'node:crypto'\n\nimport { isValidWslUsername, joinUnc, parseWslUnc, windowsToMntPath } from '../shared/paths.ts'\nimport { getWindowsWorkspace, getWorkspaceUsername } from '../shared/wsl-credentials.ts'\nimport { defaultDistroSync } from '../shared/wsl.ts'\nimport { bridgeEnv } from '../shared/wsl-env.ts'\nimport { STDIN_CAP_BYTES, stdinRefusal } from '../shared/wsl-stdin.ts'\nimport { SESSION_ARGV } from './wsl-bash-protocol.ts'\nimport { WslBashSession, type WslBashRun, type WslBashSessionSpec, type WslBashSpawnHost } from './wsl-bash-session.ts'\nimport { startBackgroundJob } from './wsl-jobs.ts'\nimport { retryNote, starveNote } from './wsl-bash-starve.ts'\nimport { normaliseTtyOutput, wrapForTty } from './wsl-bash-tty.ts'\n\n/** The tool name — the same one the host's tools register, so only one may be mounted. */\nexport const TOOL_NAME = 'bash'\n\n/** Plugin config. */\nexport interface Config {\n  /** Default per-call deadline in milliseconds. */\n  timeoutMs?: number\n  /** Ceiling a call may ask for. */\n  maxTimeoutMs?: number\n  /** Per-stream cap before the tail is kept and `truncated` is set. */\n  maxOutputBytes?: number\n  /** SIGTERM→SIGKILL grace for the child. */\n  graceMs?: number\n  /** How long the shell may take to come up, including its bootstrap. */\n  bootTimeoutMs?: number\n  /** Distribution; empty means resolve from the session path, then `DSH_WSL_DISTRO`, then default. */\n  distro?: string\n  /** Linux user; empty means the stored workspace user, then `DSH_WSL_USER`, then the default. */\n  username?: string\n}\n\n/**\n * The defaults as data as well as schema fields: a world row mounted without a `config:` block gets\n * an undefined config, and schemastery's defaults are not applied on that path.\n */\nconst DEFAULTS: Required<Pick<Config, 'timeoutMs' | 'maxTimeoutMs' | 'maxOutputBytes' | 'graceMs' | 'bootTimeoutMs'>> = {\n  timeoutMs: 120_000,\n  maxTimeoutMs: 600_000,\n  maxOutputBytes: 256 * 1024,\n  graceMs: 3_000,\n  bootTimeoutMs: 20_000,\n}\n\nexport const Config: z<Config> = z.object({\n  timeoutMs: z.number().default(DEFAULTS.timeoutMs),\n  maxTimeoutMs: z.number().default(DEFAULTS.maxTimeoutMs),\n  maxOutputBytes: z.number().default(DEFAULTS.maxOutputBytes),\n  graceMs: z.number().default(DEFAULTS.graceMs),\n  bootTimeoutMs: z.number().default(DEFAULTS.bootTimeoutMs),\n  distro: z.string().default(''),\n  username: z.string().default(''),\n})\n\n/** A config with every numeric knob resolved; empty strings mean \"not set\". */\ntype ResolvedConfig = typeof DEFAULTS & Config\n\n/** The defaults as a resolved config, for callers that build a spec before a plugin row exists. */\nexport const PROBE_CONFIG: ResolvedConfig = { ...DEFAULTS }\n\n/**\n * Declared for readers and for a host that mounts the module object. The host's loader\n * (`cordis-plugin-loader`, `unwrapExports`) hands cordis `exports.default` — this module's bare\n * `apply` — so neither `inject` nor `Config` reaches the fiber, and `ctx.subprocess` then throws\n * `cannot get property \"subprocess\" without inject`. The code below therefore resolves the seam with\n * `ctx.get('subprocess')`, which bypasses the inject requirement, as the rest of this plugin does.\n */\nexport const inject = ['subprocess']\n\n/** The tool-execution face this tool reads. */\ninterface ToolExecution {\n  callId?: string\n  agent?: { id?: string; session?: { id?: string; header?: { cwd?: string } } }\n  signal?: AbortSignal\n}\n\n/** The arguments the model may pass. */\ninterface BashArgs {\n  command: string\n  description?: string\n  workdir?: string\n  timeoutMs?: number\n  tty?: boolean\n  run_in_background?: boolean\n  stdin?: string\n}\n\n/**\n * The ceiling on one call's `stdin`, and the refusal it earns when exceeded, both live in\n * `src/shared/wsl-stdin.ts` — see the note there for why a test must not need this module.\n */\n\n/** Environment facts that must reach the distribution. */\nconst BRIDGED_KEYS = ['DSH_HOME', 'DSH_SESSION_ID', 'DSH_SHELL', 'DSH_WSL_DISTRO', 'DSH_WSL_USER', 'DSH_WSL_SESSION', 'NO_COLOR', 'TERM', 'PAGER', 'GIT_PAGER']\n\n/** Model-friendly overrides, matching the one-shot executor's set. */\nconst ENV_OVERRIDES: Record<string, string> = {\n  NO_COLOR: '1',\n  TERM: 'dumb',\n  PAGER: 'cat',\n  GIT_PAGER: 'cat',\n}\n\n/** The Linux form of a session path: UNC, absolute Linux, or a Windows drive path. */\nfunction linuxOf(path: string | undefined): string | undefined {\n  if (path === undefined || path === '') return undefined\n  const unc = parseWslUnc(path)\n  if (unc !== null) return unc.linuxPath\n  if (path.startsWith('/')) return path\n  return windowsToMntPath(path) ?? undefined\n}\n\n/**\n * The Linux directory a call runs in.\n *\n * A relative `workdir` is joined onto the session's own directory, which is what the host's one-shot\n * tool does (`dsh-tool-bash`'s `resolveWorkdir`); measured there, `workdir: \"docs\"` becomes\n * `/home/<session-user>/docs` and the `cd` fails with bash's own `No such file or directory`. Translating it\n * to nothing instead would run the command somewhere the model did not ask for, silently.\n *\n * @param args - the model's arguments.\n * @param exec - the tool execution, whose agent session carries the workspace path.\n * @returns the path for the call's `cd`, or undefined to let the session stay where it is.\n */\nfunction resolveCwd(args: BashArgs, exec: ToolExecution): string | undefined {\n  if (args.workdir === undefined || args.workdir === '') return undefined\n  if (args.workdir.startsWith('/') || parseWslUnc(args.workdir) !== null) return linuxOf(args.workdir)\n  const base = linuxOf(exec.agent?.session?.header?.cwd)\n  if (base === undefined) return linuxOf(args.workdir)\n  return `${base.replace(/\\/+$/, '')}/${args.workdir.replace(/^\\.?\\/+/, '')}`\n}\n\n/**\n * The distribution a call runs in: config, then the session path, then `DSH_WSL_USER`-style facts,\n * then the host default — the same order the one-shot executor uses.\n */\nfunction resolveDistro(config: ResolvedConfig, headerCwd: string | undefined): string {\n  if (config.distro !== undefined && config.distro !== '') return config.distro\n  const unc = headerCwd === undefined ? null : parseWslUnc(headerCwd)\n  if (unc !== null) return unc.distro\n  const fromEnv = process.env.DSH_WSL_DISTRO\n  if (fromEnv !== undefined && fromEnv !== '') return fromEnv\n  return defaultDistroSync() ?? ''\n}\n\n/**\n * The Linux user a call runs as.\n *\n * The chain is the one `src/shell.ts` resolves, in the same order, so the persistent tier and\n * the one-shot fallback agree about who a workspace runs as: the session's own fact\n * (`DSH_WSL_USER`, contributed by the host half), then the workspace's stored username, then\n * the configured one. The stored step was missing here: the store is keyed by the workspace\n * path, the one-shot executor reads it, the dialog writes it — and a WSL workspace configured\n * for a user other than the distribution's default silently ran as that default instead.\n * @param config - the resolved plugin configuration.\n * @param headerCwd - the session's workspace path, when it has one.\n * @returns the username, or undefined for the distribution default user.\n */\nfunction resolveUser(config: ResolvedConfig, headerCwd: string | undefined): string | undefined {\n  const unc = headerCwd === undefined ? null : parseWslUnc(headerCwd)\n  const stored = unc !== null\n    ? getWorkspaceUsername(joinUnc(unc.distro, unc.linuxPath))\n    : headerCwd !== undefined && /^[A-Za-z]:[\\\\/]/.test(headerCwd) ? getWindowsWorkspace(headerCwd)?.username : undefined\n  const candidates = [process.env.DSH_WSL_USER, stored, config.username]\n  for (const candidate of candidates) {\n    if (candidate !== undefined && candidate !== '' && isValidWslUsername(candidate)) return candidate\n  }\n  return undefined\n}\n\n/**\n * The host's abort shape. `dsh-tool-bash` throws `toolAborted()` on a caller cancel — a\n * `HarnessError` reading `tool call aborted` with `name` set to `AbortError` — and the trace renders\n * that as a cancelled call. Returning a result instead would put `[exit code: 1]` on a command the\n * user stopped, which reads as if their command had failed.\n */\nfunction toolAborted(): Error {\n  const error = new Error('tool call aborted')\n  error.name = 'AbortError'\n  return error\n}\n\n/**\n * Render one finished run the way the host's tool does, so the trace text is the same shape.\n *\n * The host's own truncation sentence is `[output truncated; full output: <path>]`\n * (`dsh-tool-bash/lib/index.js:137`), copied here verbatim because a model that has learned it in one\n * world should not have to learn a second one. Anything the session did that the model could not\n * otherwise see — a restart, a skipped section, a reaped process — is appended as its own bracketed\n * line rather than left in a log the user of Desktop cannot read.\n */\n/**\n * Say which of the two paths in one answer holds the whole stream.\n *\n * The host appends its own `(Omitted … bytes. Full formatted result stored at: …)` sentence beside\n * ours, and the file that sentence names holds a *formatted excerpt*: measured 2026-10-09 on\n * `seq 1 250000`, it kept 74 890 of the 250 000 lines while our spill held all of them, and the model\n * read the excerpt first and reported that count. Both arms carry the note, because the host's excerpt\n * sits beside whichever sentence appears — and `#79` put a path in the body for stderr too.\n */\nconst SPILL_PATH_NOTE = '[the path above holds the whole stream; if this answer also names a \"formatted result\" path, that one is the host\\'s excerpt and can hold fewer lines]'\n\nfunction renderRun(value: ForegroundOutput): { type: 'text'; text: string }[] {\n  let body = value.stdout.text\n  if (value.stdout.truncated && value.stdout.spillPath !== undefined) {\n    if (body.length > 0 && !body.endsWith('\\n')) body += '\\n'\n    body += `[output truncated; full output: ${value.stdout.spillPath}]`\n    body += '\\n' + SPILL_PATH_NOTE\n  }\n  if (value.stderr.text.length > 0) {\n    if (body.length > 0 && !body.endsWith('\\n')) body += '\\n'\n    body += `[stderr]\\n${value.stderr.text}`\n  }\n  // The stderr arm of the same sentence stdout gets above, and outside the `text` guard: what the\n  // model has to be able to find is the file, which exists even when the retained window is empty.\n  // Without this a model whose command wrote 1.29 MB to fd 2 read ~400 kB of it with nothing saying\n  // the rest existed, and the file holding the rest was never named. Measured 2026-10-11:\n  // `seq 1 200000 >&2` came back `truncated: false` with a spill file beside it, because the session\n  // reported `stderrTruncated` as a constant.\n  if (value.stderr.truncated && value.stderr.spillPath !== undefined) {\n    if (body.length > 0 && !body.endsWith('\\n')) body += '\\n'\n    body += `[stderr truncated; full output: ${value.stderr.spillPath}]`\n    body += '\\n' + SPILL_PATH_NOTE\n  }\n  if (body.length === 0) body = '(no output)'\n  const markers: string[] = []\n  if (value.timedOut) markers.push(`[timed out after ${value.timeoutMs}ms]`)\n  if (value.signal !== null) markers.push(`[killed by signal: ${value.signal}]`)\n  else if (value.exitCode !== null && value.exitCode !== 0) markers.push(`[exit code: ${value.exitCode}]`)\n  markers.push(...value.notes)\n  if (markers.length === 0) return [{ type: 'text', text: body }]\n  if (!body.endsWith('\\n')) body += '\\n'\n  return [{ type: 'text', text: body + markers.join('\\n') }]\n}\n\n/** The `foreground` arm of the host tool's output union. */\ninterface ForegroundOutput {\n  kind: 'foreground'\n  exitCode: number | null\n  signal: string | null\n  timedOut: boolean\n  aborted: boolean\n  timeoutMs: number\n  stdout: { text: string; truncated: boolean; spillPath?: string }\n  stderr: { text: string; truncated: boolean; spillPath?: string }\n  /** What the session did on this call that the model could not otherwise see. */\n  notes: string[]\n}\n\n/** The `background` arm of the host tool's output union. */\ninterface BackgroundOutput {\n  kind: 'background'\n  jobId: string\n}\n\n/**\n * How many times each exact command has been attempted since this shell started, per session. A\n * `WeakMap` on the session object so a rebuild — which *is* a change in the environment — starts a\n * clean count, and so nothing outlives the shell it describes.\n */\nconst attempts = new WeakMap<WslBashSession, Map<string, number>>()\n\n/** Shape a session run into the host's result contract. */\nfunction toForeground(run: WslBashRun, timeoutMs: number, escalated: boolean, before: string[] = [],\n  repeats = 0): ForegroundOutput {\n  const killed = run.exitCode < 0\n  // Whatever the session did that the model cannot see goes first, because it changes how to read the\n  // body: a command that was stopped and run again answers differently from one that ran once.\n  const notes: string[] = [...before]\n  if (run.starved !== undefined) {\n    notes.push(starveNote(run.starved, run.starvedAtMs ?? timeoutMs, run.starvedViaRoot === true, run.starvedShellInterrupt === true))\n  }\n  if (run.timedOut) {\n    // The check that would have caught a keyboard wait did not run here. Said out loud, because the\n    // alternative is a deadline reached with no reason attached — and a reader would conclude the wait\n    // had been examined and found to be normal.\n    if (run.starveProbeBroken === true) {\n      notes.push('[the check for a command waiting on a keyboard could not run in this distribution — its `/proc` walk did not answer — so nothing was stopped early: if this command was waiting for input, pass `tty: true`, run it in a `wsl_terminal` session, or ask a person to run it in the right sidebar\\'s terminal tab]')\n    }\n    // Only say a restart happened when the session says it did — measured, not assumed, by the cell\n    // that times out an escalated `sleep`.\n    if (run.restarted) {\n      notes.push('[the shell was restarted to recover; for work that outlives one call pass run_in_background: true, or use bash_background]')\n    }\n    else {\n      notes.push('[the call reached its deadline; for work that outlives one call pass run_in_background: true, or use bash_background]')\n    }\n    // The reading ran, saw processes, and none of them matched a terminal wait. Print what it read and\n    // which fields it read it from: on a kernel that exposes the wait this line carries the sleep\n    // location and the foreground job (`w=wait_woken 1tty fg`); on the WSL1 runner (CI frame\n    // 37494104075) `wchan` and `syscall` both come back empty for every process, asleep or running, and\n    // the line says `w=not-reported` instead.\n    // Without the fields named, either shape reads as though the wait had been examined and found\n    // ordinary — which is the one claim this layer must not make about a kernel it cannot read.\n    if (run.starveSaw !== undefined) {\n      notes.push('[the check for a command waiting on a keyboard looked and read '\n        + `(/proc/<pid>/wchan, /proc/<pid>/syscall, its fd table): ${run.starveSaw}]`)\n    }\n  }\n  // The command asked for the shell to end — `… ; exit 3`, a `set -e` body, a script that finishes with\n  // `exit`. That is not a cancelled call, and the reply a cancellation produces (`Error: tool call\n  // aborted`, no streams) is the one answer that tells the model nothing about what its own command did.\n  // Measured on the installed 0.7.7 build: this shape came back with nothing, and the evidence that the\n  // shell had been rebuilt arrived on the *next* call, where it reads as that call's own event.\n  if (run.shellExited) {\n    notes.push('[this command ended the session shell itself (bash left with the code reported here), so it was run once more after the shell was rebuilt: anything it did before ending has been done twice, and this answer is from that second run. A command that must exit non-zero without ending its shell should wrap itself in its own `bash -c` body, or use `wsl_terminal`]')\n  }\n  if (run.restarted) {\n    notes.push(run.skipped === undefined || run.skipped.length === 0\n      ? '[the shell was restarted and its directory, exported variables, options and aliases were replayed]'\n      : `[the shell was restarted; not restored: ${run.skipped.join(', ')}]`)\n  }\n  if (run.reaped !== undefined && run.reaped > 0) {\n    notes.push(`[${run.reaped} detached process${run.reaped === 1 ? '' : 'es'} from the previous shell ${run.reaped === 1 ? 'was' : 'were'} stopped]`)\n  }\n  // `sudo` reaches its password prompt now (the call is given a pseudo-terminal), but there is nobody\n  // on the other end to type into it, and sudo's own words do not say what the caller can do about it.\n  // Searched across both streams on purpose: a pseudo-terminal folds the command's stderr into its\n  // stdout, so a check on `run.stderr` alone was measured never matching a real `sudo true`.\n  if (escalated && run.exitCode !== 0 && /sudo: (a password is required|no password was provided)/.test(`${run.stdout}\\n${run.stderr}`)) {\n    // The first way out is the one a person can take immediately: the product has interactive terminal\n    // tabs in the right sidebar (`dsh-client-ui-sidebar-terminal`), which run the host's own PTY and are\n    // not this shell — a human there can type the password. The agent's own door is named second, with\n    // the fact that makes it usable at all (the password has to come from the user), and making the\n    // session user passwordless is the third — the one that removes the prompt instead of answering it.\n    notes.push('[sudo asked for a password and this shell has nobody to type it: a person can run this once in the right sidebar\\'s terminal tab; an agent-side answer is `wsl_terminal` (open a terminal, type the password the user gives you there — never guess one); or give the session user NOPASSWD in sudoers (or start the session as root with DSH_WSL_USER) so the agent can run it alone]')\n  }\n  // The attribution line. An escalated call that did not succeed, and is not explained above, says so\n  // itself: one line naming the layer and the comparison that settles it, so a failure nobody predicted\n  // is traced to the pseudo-terminal or ruled out in one call — instead of a person reading a shell\n  // transcript wondering whether the shell is what broke.\n  if (escalated && (run.exitCode !== 0 || run.timedOut)\n    && !notes.some(note => /password|keyboard|terminal/.test(note))) {\n    notes.push('[this call ran on a pseudo-terminal (`script -qec`, one stream): re-run the same command with `tty: false` to rule this layer out before looking anywhere else]')\n  }\n  // The loop brake, deliberately not a refusal. A command that has now failed twice with the same\n  // bytes in the same shell is not going to answer differently on the third try, and the expensive\n  // thing here is the model spending another turn finding that out — but the tool cannot tell \"the\n  // environment is stuck\" from \"the third attempt is the one that fixes it\" (`npm test` after an\n  // install is the ordinary case), so it says the repetition out loud and runs the command anyway.\n  if (repeats >= 2 && (run.exitCode !== 0 || run.timedOut)) {\n    notes.push(`[this exact command has failed ${repeats} times in this shell with nothing succeeding in it since: it will answer the same way — change the command (a non-interactive flag, a different tool, an absolute path) or stop and report that it cannot be done here]`)\n  }\n  return {\n    kind: 'foreground',\n    exitCode: killed ? null : run.exitCode,\n    signal: null,\n    timedOut: run.timedOut,\n    aborted: run.aborted,\n    timeoutMs,\n    stdout: {\n      text: escalated ? normaliseTtyOutput(run.stdout) : run.stdout,\n      truncated: run.truncated,\n      ...(run.stdoutSpillPath === undefined ? {} : { spillPath: run.stdoutSpillPath }),\n    },\n    stderr: {\n      text: escalated ? normaliseTtyOutput(run.stderr) : run.stderr,\n      truncated: run.stderrTruncated,\n      ...(run.stderrSpillPath === undefined ? {} : { spillPath: run.stderrSpillPath }),\n    },\n    notes,\n  }\n}\n\nconst STREAM_SCHEMA = {\n  type: 'object',\n  additionalProperties: false,\n  required: true,\n  properties: {\n    text: { type: 'string', required: true },\n    truncated: { type: 'boolean', required: true },\n    spillPath: { type: 'string' },\n  },\n} as const\n\n/**\n * The session spec for one workspace path: which distribution and user, and the child's argv.\n *\n * Exported because the boot-time mount decision has to build exactly the session the tool will\n * later build — probing a different argv than the one that ships is how a readiness check can pass\n * a world that then fails every call.\n *\n * @param config - the resolved plugin configuration.\n * @param headerCwd - the session's workspace path, UNC or Linux.\n * @returns the spec, or undefined when no distribution could be resolved.\n */\nexport function buildSessionSpec(config: ResolvedConfig, headerCwd: string | undefined, sessionId?: string): WslBashSessionSpec | undefined {\n  const distro = resolveDistro(config, headerCwd)\n  if (distro === '') return undefined\n  const user = resolveUser(config, headerCwd)\n  const linuxCwd = linuxOf(headerCwd)\n  // One token per session, carried by every process the shell starts. It is what lets a rebuild stop\n  // the children that detached themselves from the shell without touching a process the user owns.\n  const sessionToken = randomUUID()\n  const prefix = ['wsl.exe', '-d', distro, ...(user === undefined ? [] : ['-u', user])]\n  return {\n    argv: [...prefix, ...(linuxCwd === undefined ? [] : ['--cd', linuxCwd]), '-e', 'bash', ...SESSION_ARGV],\n    // The reaper runs a script of its own, so it gets the same distribution and user without the\n    // session's working directory: it is not running the user's command.\n    reaperArgv: [...prefix, '-e', 'bash', '-c'],\n    // The witness: the same probe, run as the distribution's root, for a process that hides its own\n    // `/proc` entries (`sudo` clears its dumpable flag). It is what turns an unconfirmable wait into a\n    // reading, so the tool never has to wait out a long silence to be sure — and when root is not\n    // available here the probe simply does not answer, which the session records.\n    witnessArgv: ['wsl.exe', '-d', distro, '-u', 'root', '-e', 'bash', '-c'],\n    // The child never starts inside the UNC share: spawning with a UNC cwd is a documented\n    // Node/Windows edge, and `wsl.exe --cd` already decides the Linux side.\n    cwd: process.env.SystemRoot ?? 'C:\\\\Windows',\n    env: bridgeEnv(\n      {\n        ...ENV_OVERRIDES,\n        // Parity with the host's own persistent shell: @deepseek-ai/dsh-terminal-bash\n        // sets both facts in every PTY child's environment, so a shell that cannot say\n        // which session owns it is not the shell the host contracts for.\n        DSH_SHELL: '1',\n        ...(sessionId === undefined || sessionId === '' ? {} : { DSH_SESSION_ID: sessionId }),\n        DSH_WSL_DISTRO: distro,\n        DSH_WSL_SESSION: sessionToken,\n        ...(user === undefined ? {} : { DSH_WSL_USER: user }),\n      },\n      BRIDGED_KEYS,\n    ),\n    graceMs: config.graceMs,\n    bootTimeoutMs: config.bootTimeoutMs,\n    maxOutputBytes: config.maxOutputBytes,\n    sessionToken,\n  }\n}\n\n/**\n * Mount the tool.\n * @param ctx - the host context, providing `subprocess` and the tools registry.\n * @param config - plugin configuration; a row without a `config:` block mounts with none.\n */\nexport function apply(ctx: Context, config?: Config): void {\n  const resolved: ResolvedConfig = { ...DEFAULTS, ...config === undefined ? {} : config }\n  const tools = ctx.get('tools') as unknown as { register?: (tool: unknown) => (() => void) | void } | undefined\n  if (tools?.register === undefined) return\n  // The host's own log is the other half of attribution: a line here is what someone reading the\n  // backend's output (or a crash log) finds without reopening a session. Optional by design — an\n  // older host without the service must not lose the call over a log line.\n  const logging = ctx.get('logger') as { debug?: (message: string, ...fields: unknown[]) => void } | undefined\n\n  // `ctx.get` rather than `ctx.subprocess`, even though `inject` names the service: the host's\n  // loader passes `exports.default ?? exports` to `ctx.plugin`, so a module-level `inject` never\n  // reaches the fiber and every property access the tool made threw\n  // `cannot get property \"subprocess\" without inject`. It passed 13/13 in a driver that mounted the\n  // module object directly, and failed every call in Desktop.\n  const spawnHost = (): WslBashSpawnHost => {\n    const subprocess = ctx.get('subprocess') as unknown as WslBashSpawnHost['subprocess'] | undefined\n    if (subprocess === undefined || typeof subprocess.spawn !== 'function') {\n      throw new Error('wsl-bash: this host exposes no subprocess service to start a shell with')\n    }\n    return { subprocess }\n  }\n\n  const sessions = new Map<string, WslBashSession>()\n  const cleanup = () => {\n    for (const session of sessions.values()) void session.dispose()\n    sessions.clear()\n  }\n  ctx.effect?.(() => cleanup)\n\n  const tool = defineTool({\n    name: TOOL_NAME,\n    description: 'Run a bash command inside this WSL distribution. The shell is persistent: `cd`, exported variables, activated virtualenvs, aliases and shell functions survive between calls, so use absolute paths or an explicit `cd` when a call must not depend on where the last one left off. A command that reads from stdin is given /dev/null unless the call passes `stdin`. A command that instead reaches for the keyboard (`sudo`, `ssh`, an editor, a database client asking for a password) is caught by watching the process rather than guessed from its name: when a call goes silent with nothing running, the tool stops it and runs it again on a pseudo-terminal of its own inside the same call, so the body is the program\\'s own complaint about having no terminal. A live display (`top`, `htop`) exits on its own without a terminal, so ask for `top -bn1` unless you pass `tty: true`. For work that must outlive one call pass `run_in_background: true` — it starts a tracked job (`job_output` to read, `job_kill` to stop) in a separate process, so it does not see this shell\\'s `cd` or `export`. Nothing in this shell can be typed into, so a prompt there is unanswerable her